// Reproducible draw of 5 references per run for case-a-dark-matter scoring.
// Usage: node sample.mjs <normalised-dir> <seed-hex>
import { createHash } from "node:crypto";
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

const [dir, seed] = process.argv.slice(2);

function mulberry32(a) {
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// sha256 over the seed as an ASCII/UTF-8 string, first 8 hex chars read as uint32.
const digest = createHash("sha256").update(seed, "utf8").digest("hex");
const state = parseInt(digest.slice(0, 8), 16) >>> 0;

const testRng = mulberry32(state);
const testVector = Array.from({ length: 5 }, () => testRng());

// One stream for the whole campaign, records consumed in ascending id order.
const rng = mulberry32(state);
const ids = readdirSync(dir)
  .filter((f) => f.endsWith(".json"))
  .map((f) => f.slice(0, -5))
  .sort();

const draws = {};
for (const id of ids) {
  const record = JSON.parse(readFileSync(join(dir, `${id}.json`), "utf8"));
  const n = record.sources.length;
  if (n !== record.source_count) throw new Error(`${id}: source_count mismatch`);
  const picked = [];
  // Rejection of duplicates: draw floor(rng()*n) until 5 distinct indices.
  while (picked.length < Math.min(5, n)) {
    const i = Math.floor(rng() * n);
    if (!picked.includes(i)) picked.push(i);
  }
  draws[id] = { n, indices_in_draw_order: picked };
}

console.log(
  JSON.stringify(
    { sha256_of_seed: digest, uint32_state: state, first_five_outputs: testVector, draws },
    null,
    2,
  ),
);
